// Especificação Formal em Lógica de Hoare:
// {P: x == X ∧ y == Y}
temp := x;
x := y;
y := temp;
// {Q: x == Y ∧ y == X}
// Prova: wp("y := temp", x == Y ∧ y == X) = (x == Y ∧ temp == X)
// wp("x := y", x == Y ∧ temp == X) = (y == Y ∧ temp == X)
// wp("temp := x", y == Y ∧ temp == X) = (y == Y ∧ x == X) ≡ P (Provado!)
